const upsertEventRegistration = `-- name: UpsertEventRegistration :one
INSERT INTO event_registrations (event_id, user_id, people, needs_lodging, departure_city)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (event_id, user_id) DO UPDATE
SET people = EXCLUDED.people,
    needs_lodging = EXCLUDED.needs_lodging,
    departure_city = EXCLUDED.departure_city,
    updated_at = now()
RETURNING event_id, user_id, people, needs_lodging, departure_city, created_at, updated_at
`

type UpsertEventRegistrationParams struct {
	EventID       int64  `json:"event_id"`
	UserID        int64  `json:"user_id"`
	People        int32  `json:"people"`
	NeedsLodging  bool   `json:"needs_lodging"`
	DepartureCity string `json:"departure_city"`
}

func (q *Queries) UpsertEventRegistration(ctx context.Context, arg UpsertEventRegistrationParams) (EventRegistration, error) {
	row := q.db.QueryRowContext(ctx, upsertEventRegistration,
		arg.EventID,
		arg.UserID,
		arg.People,
		arg.NeedsLodging,
		arg.DepartureCity,
	)
	var i EventRegistration
	err := row.Scan(
		&i.EventID,
		&i.UserID,
		&i.People,
		&i.NeedsLodging,
		&i.DepartureCity,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
